class MuseumApp extends StatelessWidget{const MuseumApp({super.key});@override Widget build(BuildContext c)=>MaterialApp(debugShowCheckedModeBanner:false,title:'Museum Explorer',theme:ThemeData(colorScheme:ColorScheme.fromSeed(seedColor:Colors.brown),useMaterial3:true),initialRoute:'/',routes:{'/':(_)=>const GalleryPage(),'/exhibit':(_)=>const ExhibitPage()});}
