class _ExhibitPageState extends State<ExhibitPage>{bool saved=false;int visits=1;@override Widget build(BuildContext c){final name=ModalRoute.of(c)?.settings.arguments as String? ?? 'The Blue Hour';return Scaffold(appBar:AppBar(title:const Text('Exhibit details'),leading:IconButton(onPressed:()=>Navigator.pop(c),icon:const Icon(Icons.arrow_back))),body:ListView(padding:const EdgeInsets.all(16),children:[GestureDetector(onDoubleTap:()=>setState(()=>saved=!saved),onLongPress:()=>ScaffoldMessenger.of(c).showSnackBar(const SnackBar(content:Text('Curator note: explore the brushwork closely.'))),child:ClipRRect(borderRadius:BorderRadius.circular(16),child:Image.network('https://picsum.photos/seed/museum1/800/360',height:220,fit:BoxFit.cover))),const SizedBox(height:18),Text(name,style:const TextStyle(fontSize:26,fontWeight:FontWeight.bold)),const Text('Modern Art • Gallery 02'),const SizedBox(height:12),const Text('An interactive exhibit page demonstrating route arguments, navigation, gestures and local state.'),Row(children:[IconButton(onPressed:()=>setState(()=>saved=!saved),icon:Icon(saved?Icons.bookmark:Icons.bookmark_border)),Text(saved?'Saved':'Save exhibit'),const Spacer(),IconButton(onPressed:()=>setState(()=>visits=visits>1?visits-1:1),icon:const Icon(Icons.remove)),Text('Visits: $visits'),IconButton(onPressed:()=>setState(()=>visits++),icon:const Icon(Icons.add))]),FilledButton(onPressed:()=>ScaffoldMessenger.of(c).showSnackBar(const SnackBar(content:Text('Added to your museum itinerary'))),child:const Text('Add to itinerary'))]));}}
